"""云端 LLM —— DeepSeek API。用于复杂对话，3-5s 返回高质量回复。"""

import json
import time
from typing import Generator, Optional

import requests

from config.settings import CloudLLMSettings, get_settings


class CloudLLMError(RuntimeError):
    pass


class CloudLLMClient:
    """DeepSeek API 客户端（OpenAI 兼容协议）。

    用法::

        llm = CloudLLMClient()
        for sentence in llm.chat_sentences("你好"):
            tts.speak(sentence)
    """

    def __init__(self, settings: Optional[CloudLLMSettings] = None):
        self.cfg = settings or get_settings().cloud_llm

    def chat_sentences(self, user_text: str, split: bool = True) -> Generator[str, None, None]:
        """流式对话。split=False 时返回完整回复（vision-4 需要等 [ACTION] 标签）。"""
        if not split:
            # ★ vision-4: 累积完整回复再返回
            full = ""
            for token in self._chat_stream(user_text):
                full += token
            if full.strip():
                yield full.strip()
            return

        buffer = ""
        for token in self._chat_stream(user_text):
            buffer += token
            sentence, buffer = self._split_sentence(buffer)
            if sentence:
                yield sentence
        if buffer.strip():
            yield buffer.strip()

    def _chat_stream(self, user_text: str) -> Generator[str, None, None]:
        if not self.cfg.api_key:
            raise CloudLLMError("未设置 VISION3_CLOUD_LLM_KEY 环境变量")

        payload = {
            "model": self.cfg.model,
            "messages": [
                {"role": "system", "content": self.cfg.system_prompt},
                {"role": "user", "content": user_text},
            ],
            "temperature": self.cfg.temperature,
            "max_tokens": self.cfg.max_tokens,
            "stream": True,
            # ★ 禁用思考链（DeepSeek v4 默认开启，否则 content 全为 null）
            "thinking": {"type": "disabled"},
        }
        headers = {
            "Authorization": f"Bearer {self.cfg.api_key}",
            "Content-Type": "application/json",
        }

        t0 = time.time()
        try:
            resp = requests.post(
                self.cfg.api_url, json=payload, headers=headers,
                timeout=self.cfg.timeout, stream=True,
            )
            if resp.status_code != 200:
                raise CloudLLMError(
                    f"DeepSeek API 返回 {resp.status_code}: {resp.text[:200]}"
                )
            for line in resp.iter_lines(decode_unicode=False):
                if not line:
                    continue
                try:
                    line_str = line.decode("utf-8")
                except UnicodeDecodeError:
                    continue
                if not line_str.startswith("data:"):
                    continue
                data_str = line_str[len("data:"):].strip()
                if data_str == "[DONE]":
                    break
                try:
                    chunk = json.loads(data_str)
                    choices = chunk.get("choices", [])
                    if choices:
                        delta = choices[0].get("delta", {})
                        # 优先 content，兜底 reasoning_content（思考模式未关闭时）
                        content = delta.get("content") or delta.get("reasoning_content") or ""
                        if content:
                            yield content
                except json.JSONDecodeError:
                    continue
        except requests.exceptions.Timeout:
            raise CloudLLMError("DeepSeek API 超时")
        except requests.exceptions.ConnectionError:
            raise CloudLLMError("DeepSeek API 连接失败")

        elapsed = time.time() - t0
        print(f"[Cloud LLM] {elapsed:.1f}s")

    def _split_sentence(self, text: str):
        """在标点处分割句子，但不切割 [ACTION...] 或 [情绪] 标签。"""
        best_pos = -1
        best_end = 0
        for ending in self.cfg.sentence_endings:
            pos = text.find(ending)
            if pos != -1:
                end_pos = pos + len(ending)
                if best_pos == -1 or pos < best_pos:
                    best_pos = pos
                    best_end = end_pos
        if best_pos >= 0:
            remaining = text[best_end:].strip()
            # 不切割紧跟的标签：如 "好的！[ACTION:motor.forward(2)]"
            if remaining.startswith("[ACTION") or remaining.startswith("[开心") or \
               remaining.startswith("[难过") or remaining.startswith("[惊讶") or \
               remaining.startswith("[生气") or remaining.startswith("[思考") or \
               remaining.startswith("[安慰") or remaining.startswith("[普通"):
                return "", text  # 等待更多内容
            return text[:best_end].strip(), text[best_end:]
        return "", text

