            buffer += token
            sentence, buffer = self._split_sentence(buffer)
            if sentence:
                yield sentence
        if buffer.strip():
            yield buffer.strip()

    def _chat_stream(self, user_text: str) -> Generator[str, None, None]:
        payload = {
            "model": self.cfg.model,
            "messages": [
                {"role": "system", "content": self.cfg.system_prompt},
                {"role": "user", "content": user_text},
            ],
            "temperature": self.cfg.temperature,
            "max_tokens": self.cfg.max_tokens,
            "stream": True,
        }
        t0 = time.time()
        try:
            resp = requests.post(
                self.cfg.server_url, json=payload,
                timeout=self.cfg.timeout, stream=True,
            )
            resp.raise_for_status()
            for line in resp.iter_lines(decode_unicode=False):
                if not line:
                    continue
                try:
                    line_str = line.decode("utf-8")
                except UnicodeDecodeError:
                    continue
                if not line_str.startswith("data:"):
                    continue
                data_str = line_str[len("data:"):].strip()
                if data_str == "[DONE]":
                    break
                try:
                    chunk = json.loads(data_str)
                    choices = chunk.get("choices", [])
                    if choices:
                        content = choices[0].get("delta", {}).get("content", "")
                        if content:
                            yield content
                except json.JSONDecodeError:
                    continue
        except requests.exceptions.ConnectionError:
            raise LocalLLMError("本地 LLM 未启动")
        except requests.exceptions.Timeout:
            raise LocalLLMError("本地 LLM 超时")

        elapsed = time.time() - t0
        print(f"[Local LLM] {elapsed:.1f}s")

    def _split_sentence(self, text: str):
        best_pos = -1
        best_end = 0
        for ending in self.cfg.sentence_endings:
            pos = text.find(ending)
            if pos != -1:
                end_pos = pos + len(ending)
                if best_pos == -1 or pos < best_pos:
                    best_pos = pos
                    best_end = end_pos
        if best_pos >= 0:
            remaining = text[best_end:].strip()
            if remaining.startswith("[ACTION") or remaining.startswith("[开心") or \
               remaining.startswith("[难过") or remaining.startswith("[惊讶") or \
               remaining.startswith("[生气") or remaining.startswith("[思考") or \
               remaining.startswith("[安慰") or remaining.startswith("[普通"):
                return "", text
            return text[:best_end].strip(), text[best_end:]
        return "", text

"""TTS 客户端 —— UART TW-TTS + Edge-TTS 双后端可切换。"""

import asyncio
import os
import subprocess
import tempfile
import time
from typing import Optional

from config.settings import TTSSettings, get_settings


class TTSClientError(RuntimeError):
    pass


class TTSClient:
    """双后端 TTS：UART 硬件 / Edge-TTS 在线 → USB 扬声器。

    在 config/user_config.json 的 tts.backend 切换: "uart" | "online"
    """

    def __init__(self, settings: Optional[TTSSettings] = None):
        self.cfg = settings or get_settings().tts
        self._uart_params_sent = False

    def speak(self, text: str, backend: Optional[str] = None) -> bool:
        be = backend or self.cfg.backend
        if be == "uart":
            return self._speak_uart(text)
        elif be == "online":
            return self._speak_online(text)
        else:
            raise TTSClientError(f"未知 TTS 后端: {be}")

    def close(self) -> None:
        self._uart_params_sent = False

    # ---- UART TW-TTS ----
    def _speak_uart(self, text: str) -> bool:
        if not text or not text.strip():
            return False
        text = text.strip()
        try:
            import serial
        except ImportError:
            raise TTSClientError("pip install pyserial")
        if not os.path.exists(self.cfg.uart_port):
            print(f"[TTS/uart] 串口不存在: {self.cfg.uart_port}")
            return False
        try:
            ser = serial.Serial(self.cfg.uart_port, self.cfg.uart_baudrate, timeout=0.5)
        except Exception as exc:
            print(f"[TTS/uart] 无法打开串口: {exc}")
            return False
        try:
            if not self._uart_params_sent:
                self._send_uart_param(ser, b"\xFD\x00\x06\x01\x01\x5B\x76", self.cfg.volume)
                time.sleep(0.1)
                self._send_uart_param(ser, b"\xFD\x00\x06\x01\x01\x5B\x73", self.cfg.speed)
                time.sleep(0.1)
                self._send_uart_param(ser, b"\xFD\x00\x06\x01\x01\x5B\x74", self.cfg.tone)
                time.sleep(0.3)
                self._uart_params_sent = True
            text_bytes = text.encode("gb2312", errors="replace")
            if len(text_bytes) == 0 or len(text_bytes) > 4094:
                return False
            frame = bytearray(5 + len(text_bytes))
            frame[0] = 0xFD
            frame[1] = ((len(text_bytes) + 2) >> 8) & 0xFF
            frame[2] = (len(text_bytes) + 2) & 0xFF
            frame[3] = 0x01
            frame[4] = 0x00
            frame[5:] = text_bytes
            ser.write(bytes(frame))
            ser.flush()
            return True
        finally:
            ser.close()

    @staticmethod
    def _send_uart_param(ser, prefix: bytes, level: int) -> None:
        level = max(0, min(9, level))
        ser.write(bytes(prefix) + bytes([0x30 + level, 0x5D]))
        ser.flush()

    # ---- Edge-TTS 在线 → USB 扬声器 ----
    def _speak_online(self, text: str) -> bool:
        if not text or not text.strip():
            return False
        text = text.strip()
        try:
            import edge_tts
        except ImportError:
            print("[TTS/online] pip install edge-tts")
            return False
        tmp = tempfile.NamedTemporaryFile(suffix=".mp3", delete=False)
        tmp.close()
        mp3_path = tmp.name
        try:
            async def _synth():
                comm = edge_tts.Communicate(text, self.cfg.online_voice)
                await comm.save(mp3_path)
            try:
                loop = asyncio.get_event_loop()
            except RuntimeError:
                loop = asyncio.new_event_loop()
                asyncio.set_event_loop(loop)
            loop.run_until_complete(_synth())
            dev = self.cfg.speaker_device
            subprocess.run(
                ["aplay", "-D", dev, "-q", mp3_path],
                timeout=15,
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            )
            return True
        except FileNotFoundError:
            print("[TTS/online] aplay 未安装 (sudo apt install alsa-utils)")
            return False
        except Exception as exc:
            print(f"[TTS/online] {exc}")
            return False
        finally:
            try:
                os.unlink(mp3_path)
            except OSError:
                pass

